glsl:
vec3 heat(float t) {
  return clamp(vec3(smoothstep(0.25, 0.6, t) + smoothstep(0.85, 1.0, t),
                    smoothstep(0.5, 0.9, t),
                    smoothstep(0.0, 0.25, t) - smoothstep(0.35, 0.55, t) + smoothstep(0.92, 1.0, t)), 0.0, 1.0);
}
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  return vec4(mix(c.rgb, heat(luma(c.rgb)), uAmount), c.a);
}
